turn_private.lock_text_work(uuid,uuid).body:
declare w turn_private.work%rowtype; c turn_private.text_content%rowtype;
begin
  select * into w from turn_private.work where turn_id=p_turn;
  if not found or p_token is null or not turn_private.lock_turn(w.turn_id,w.owner_id,w.session_id) then return false; end if;
  select * into w from turn_private.work where turn_id=p_turn for update;
  if not found or w.state<>'leased' or w.lease_token is distinct from p_token or w.expires_at<=clock_timestamp()
    or not exists(select 1 from public.turns where id=p_turn and status not in ('completed','proposal_ready','unavailable','failed','cancelled')) then return false; end if;
  select * into c from turn_private.text_content where turn_id=p_turn and owner_id=w.owner_id and hidden_at is null;
  if not found or not turn_private.text_policy_current(c.policy_id) or exists(select 1 from turn_private.text_policies where id=c.policy_id and context_mode='qa_session_history_v1') then return false; end if;
  if exists(select 1 from turn_private.service_task_turns where turn_id=p_turn)
    and not exists(select 1 from turn_private.service_task_turns l
      join turn_private.service_tasks s on s.id=l.task_id and s.owner_id=c.owner_id and s.thread_id=c.thread_id
      join turn_private.text_content g on g.turn_id=s.goal_turn_id and g.hidden_at is null
      join public.turns t on t.id=g.turn_id and t.owner_id=c.owner_id
      where l.turn_id=p_turn and s.policy_id=c.policy_id and s.consent_id=c.consent_id)
    then return false; end if;
  perform 1 from turn_private.text_consents where owner_id=c.owner_id and policy_id=c.policy_id and consent_id=c.consent_id and revoked_at is null for share;
  return found and w.expires_at>clock_timestamp() and (
    (select context_mode from turn_private.text_policies where id=c.policy_id) in ('current_input_v1','knowledge_intent_v1')
    or turn_private.task_history(p_turn) is not null);
end

start_text_turn(uuid,uuid,uuid,uuid,text.body:
declare u uuid:=turn_private.text_owner(); c turn_private.text_consents%rowtype; t record; prior turn_private.text_content%rowtype; admitted jsonb;
begin
  if p_turn_id is null or p_idempotency_key is null or p_locale is null or p_locale not in ('zh','en','es','ru','ar') or not turn_private.valid_text(p_text,4000) then raise exception 'INVALID_INPUT'; end if;
  if not turn_private.text_policy_current(p_policy_id) then return jsonb_build_object('kind','blocked'); end if;
  select * into c from turn_private.text_consents where owner_id=u and policy_id=p_policy_id and revoked_at is null for share;
  if not found then return jsonb_build_object('kind','blocked'); end if;
  select * into t from public.start_chat_turn(p_thread_id,p_turn_id,p_idempotency_key,'chat-state-control-v1');
  select * into prior from turn_private.text_content where turn_id=t.turn_id;
  if found then
    if prior.owner_id<>u or prior.hidden_at is not null or prior.policy_id<>p_policy_id or prior.consent_id<>c.consent_id or prior.input_text<>p_text or prior.locale<>p_locale then raise exception 'IDEMPOTENCY_KEY_REUSE'; end if;
    return jsonb_build_object('kind','accepted','turnId',t.turn_id,'reused',true);
  end if;
  if t.reused then raise exception 'IDEMPOTENCY_KEY_REUSE'; end if;
  insert into turn_private.text_content(turn_id,owner_id,thread_id,policy_id,consent_id,locale,input_text) values(t.turn_id,u,p_thread_id,p_policy_id,c.consent_id,p_locale,p_text);
  admitted:=public.enqueue_turn_work(t.turn_id,u,(auth.jwt()->>'session_id')::uuid,120000,3);
  if admitted->>'kind'<>'queued' then raise exception 'TURN_UNAVAILABLE'; end if;
  return jsonb_build_object('kind','accepted','turnId',t.turn_id,'reused',false);
end

enqueue_turn_work(uuid,uuid,uuid,integer.body:
declare w turn_private.work%rowtype; t public.turns%rowtype;
begin
  if p_lease_ms is null or p_lease_ms not between 1000 and 300000 or p_max_attempts is null or p_max_attempts not between 1 and 5 then raise exception 'INVALID_INPUT'; end if;
  if not turn_private.lock_turn(p_turn_id,p_owner_id,p_session_id) then return jsonb_build_object('kind','unavailable'); end if;
  select * into w from turn_private.work where turn_id=p_turn_id for update;
  if found then
    if w.owner_id<>p_owner_id or w.session_id<>p_session_id or w.lease_ms<>p_lease_ms or w.max_attempts<>p_max_attempts then return jsonb_build_object('kind','conflict'); end if;
    return jsonb_build_object('kind','duplicate');
  end if;
  select * into t from public.turns where id=p_turn_id;
  if t.status<>'accepted' or not exists(select 1 from public.chat_turn_events where turn_id=p_turn_id and sequence=1 and state='accepted') then return jsonb_build_object('kind','unavailable'); end if;
  insert into turn_private.work(turn_id,owner_id,session_id,lease_ms,max_attempts) values(p_turn_id,p_owner_id,p_session_id,p_lease_ms,p_max_attempts);
  return jsonb_build_object('kind','queued');
end

authorize_grounded_dispatch(uuid,uuid,uu.body:
declare payload jsonb; c turn_private.text_content%rowtype;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
 payload:=public.read_grounded_work(p_turn_id,p_lease_token);
 if payload->>'kind' is distinct from 'intent_input' or payload->>'policyId' is distinct from p_policy_id::text
   or payload->>'provider' is distinct from p_provider or payload->>'contextDigest' is distinct from p_context_digest then return jsonb_build_object('kind','blocked'); end if;
 select * into c from turn_private.text_content where turn_id=p_turn_id;
 insert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;
 if not found then return jsonb_build_object('kind','blocked'); end if;
 return jsonb_build_object('kind','authorized');
end

complete_grounded_place_work(uuid,uuid,t.body:
declare source_text text; city text; needs jsonb; item jsonb; selected jsonb; result jsonb; final_intent text; final_scope text;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) then return place_actions_private.ask_complete_v1(p_turn_id,p_lease_token,p_intent,p_request_scope,p_unanswered_needs,p_place_name);end if;
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) then return guide_private.place_complete_v1(p_turn_id,p_lease_token,p_intent,p_request_scope,p_unanswered_needs,p_place_name);end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
 if p_intent is null or p_intent not in ('place_address','place_opening_hours','place_address_and_hours')
  or p_request_scope is null or p_request_scope not in ('single','additional_needs')
  or p_place_name is null or length(p_place_name) not between 1 and 160 or p_place_name~'[[:cntrl:]]'
  or p_unanswered_needs is null or octet_length(p_unanswered_needs)>12000 then raise exception 'INVALID_INPUT'; end if;
 needs:=p_unanswered_needs::jsonb;
 if jsonb_typeof(needs) is distinct from 'array' then raise exception 'INVALID_INPUT'; end if;
 if jsonb_array_length(needs)>6 or ((p_request_scope='additional_needs')<>(jsonb_array_length(needs)>0)) then raise exception 'INVALID_INPUT'; end if;
 if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 select c.input_text,g.city into source_text,city from turn_private.text_content c
 join turn_private.grounded_turns g on g.turn_id=c.turn_id and g.owner_id=c.owner_id where c.turn_id=p_turn_id and g.completed_at is null;
 if not found then return jsonb_build_object('kind','blocked'); end if;
 if strpos(source_text,p_place_name)=0 then raise exception 'INVALID_INPUT'; end if;
 for item in select value from jsonb_array_elements(needs) loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}')!~'[^[:space:]]' or length(item#>>'{}')>240
   or strpos(source_text,item#>>'{}')=0 then raise exception 'INVALID_INPUT'; end if;
 end loop;
 if (select count(distinct value) from jsonb_array_elements(needs))<>jsonb_array_length(needs) then raise exception 'INVALID_INPUT'; end if;
 -- Same lock order as Ops: name barrier before publication row locks.
 perform pg_catalog.pg_advisory_xact_lock_shared(160047,1);
 begin
  selected:=knowledge_review_private.place_subject(p_place_name,city);
 exception when raise_exception then
  if SQLERRM<>'KNOWLEDGE_DISABLED' then raise; end if;
  return public.complete_grounded_work(p_turn_id,p_lease_token,'technical_failure','unknown');
 end;
 final_intent:=case selected->>'kind' when 'matched' then p_intent when 'ambiguous' then 'clarification' else 'unsupported' end;
 final_scope:=case when selected->>'kind'='matched' then p_request_scope else 'unknown' end;
 result:=turn_private.complete_selected_grounded_work(p_turn_id,p_lease_token,final_intent,final_scope,selected->>'subjectId');
 if result->>'kind'='finished' then
  update turn_private.grounded_turns set place_name=case when intent<>'technical_failure' then p_place_name end,
   place_resolution=case when intent<>'technical_failure' then selected->>'kind' end,
   unanswered_needs=case when request_scope='additional_needs' then needs else '[]'::jsonb end where turn_id=p_turn_id;
 end if;
 return result;
end

complete_grounded_work_with_needs(uuid,u.body:
declare needs jsonb; source_text text; item jsonb; result jsonb;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
 if p_unanswered_needs is null or octet_length(p_unanswered_needs)>12000 then raise exception 'INVALID_INPUT'; end if;
 needs:=p_unanswered_needs::jsonb;
 if jsonb_typeof(needs)<>'array' then raise exception 'INVALID_INPUT'; end if;
 if jsonb_array_length(needs)>6 or p_request_scope is null
  or ((p_request_scope='additional_needs') <> (jsonb_array_length(needs)>0)) then raise exception 'INVALID_INPUT'; end if;
 if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 select input_text into source_text from turn_private.text_content where turn_id=p_turn_id;
 if source_text is null then return jsonb_build_object('kind','blocked'); end if;
 for item in select value from jsonb_array_elements(needs) loop
  if jsonb_typeof(item)<>'string' then raise exception 'INVALID_INPUT'; end if;
  if (item#>>'{}') !~ '[^[:space:]]' or length(item#>>'{}')>240
   or strpos(source_text,item#>>'{}')=0 then raise exception 'INVALID_INPUT'; end if;
 end loop;
 if (select count(distinct value) from jsonb_array_elements(needs))<>jsonb_array_length(needs) then raise exception 'INVALID_INPUT'; end if;
 -- The existing completion owns dispatch, current evidence, deadline recheck,
 -- immutable result and terminal event. Both writes commit or roll back together.
 result:=public.complete_grounded_work(p_turn_id,p_lease_token,p_intent,p_request_scope);
 if result->>'kind'='finished' then
  update turn_private.grounded_turns set unanswered_needs=case when request_scope='additional_needs' then needs else '[]'::jsonb end
   where turn_id=p_turn_id;
 end if;
 return result;
end

turn_private.complete_selected_grounded_.body:
declare w turn_private.work%rowtype; g turn_private.grounded_turns%rowtype; answer jsonb; outcome text; failure text;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and knowledge_review_private.question_definition(p_intent) is not null and p_intent not in('place_address','place_opening_hours','place_address_and_hours') and p_request_scope in('single','additional_needs') and p_subject is null then
  if not exists(select 1 from turn_private.text_dispatches where turn_id=p_turn_id and lease_token=p_lease_token) then return jsonb_build_object('kind','blocked');end if;
  p_intent:='unsupported';p_request_scope:='unknown';
 end if;
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and knowledge_review_private.question_definition(p_intent) is not null and (p_intent not in('place_address','place_opening_hours','place_address_and_hours') or p_subject is distinct from (select selected_place_request->'basis'->>'subjectId' from turn_private.grounded_turns where turn_id=p_turn_id)) then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and knowledge_review_private.question_definition(p_intent) is not null and guide_private.answer_basis_v1(p_turn_id,p_lease_token,p_intent,p_subject) is null then return jsonb_build_object('kind','blocked');end if;
 if p_intent is null or p_request_scope is null or not (
   (knowledge_review_private.question_definition(p_intent) is not null and p_request_scope in ('single','additional_needs'))
   or (p_intent in ('clarification','unsupported','technical_failure','blocked') and p_request_scope='unknown')) then raise exception 'INVALID_INPUT'; end if;
 if (p_intent in ('place_address','place_opening_hours','place_address_and_hours')) <> (p_subject is not null) then raise exception 'INVALID_INPUT'; end if;
 if (exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null) or not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 select g0.* into g from turn_private.grounded_turns g0 join turn_private.text_content c on c.turn_id=g0.turn_id and c.owner_id=g0.owner_id
  join turn_private.text_policies p on p.id=c.policy_id and (p.context_mode='knowledge_intent_v1' or (p.context_mode='current_input_v1' and g0.selected_place_request is not null)) where g0.turn_id=p_turn_id;
 if not found or g.completed_at is not null then return jsonb_build_object('kind','blocked'); end if;
 if (knowledge_review_private.question_definition(p_intent) is not null or p_intent in ('clarification','unsupported'))
  and not exists(select 1 from turn_private.text_dispatches where lease_token=p_lease_token and turn_id=p_turn_id) then return jsonb_build_object('kind','blocked'); end if;
 if knowledge_review_private.question_definition(p_intent) is not null then
  begin
   answer:=knowledge_review_private.resolve_question(knowledge_review_private.selected_question_input(p_intent,g.city,g.locale,p_subject),case when exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) then guide_private.answer_basis_v1(p_turn_id,p_lease_token,p_intent,p_subject) else null end);
  exception when raise_exception then
   get stacked diagnostics failure=MESSAGE_TEXT;
   if failure not in ('KNOWLEDGE_DISABLED','KNOWLEDGE_CAPACITY','KNOWLEDGE_SNAPSHOT_CHANGED') then raise; end if;
   p_intent:='technical_failure';p_request_scope:='unknown';
  end;
 end if;
 outcome:=case when p_intent='technical_failure' then 'technical_failure'
  when p_intent in ('blocked','unsupported') then 'blocked' when p_intent='clarification' then 'clarification'
  when answer->'answer'->>'outcome'='no_answer' then 'blocked'
  when p_request_scope='additional_needs' or answer->'answer'->>'outcome'='partial' then 'partial' else 'answered' end;
 -- The resolver can wait on publication locks. Recheck wall-clock lease and
 -- authorization after every such wait, before committing the immutable result.
 if (exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null) or not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 select * into w from turn_private.work where turn_id=p_turn_id;
 update turn_private.grounded_turns set intent=p_intent,request_scope=p_request_scope,original_outcome=outcome,
  basis=answer->'_basis',place_subject_id=case when answer is not null then p_subject end,completed_at=clock_timestamp() where turn_id=p_turn_id;
 -- The generic output column never contains evidence, factual prose or source text.
 update turn_private.text_content set output_kind=outcome,output_text='reviewed-answer-v1' where turn_id=p_turn_id;
 perform turn_private.terminal(p_turn_id,case when outcome='technical_failure' then 'failed' when outcome='blocked' then 'unavailable' else 'completed' end,w.attempt);
 if g.selected_place_request is not null then perform place_actions_private.ask_finish_capacity_v1(p_turn_id,outcome,'reviewed-answer-v1');end if;
 return jsonb_build_object('kind','finished');
end

submit_grounded_turn(uuid,uuid,uuid,uuid.body:
declare u uuid:=turn_private.text_owner(); c turn_private.text_consents%rowtype;
  s turn_private.service_tasks%rowtype; prior turn_private.service_task_turns%rowtype;
  parent turn_private.text_content%rowtype; digest text; result jsonb;
begin
  if p_city is null or p_city not in ('shanghai','beijing','guangzhou','chongqing') or p_locale is null or p_locale not in ('zh','en') then raise exception 'INVALID_INPUT'; end if;
  if not exists(select 1 from turn_private.text_policies where id=p_policy_id and context_mode='knowledge_intent_v1') then raise exception 'DATA_POLICY_BLOCKED'; end if;
  if p_thread_id is null or p_turn_id is null or p_task_id is null or p_turn_id=p_task_id
    or p_idempotency_key is null or p_scope_version is distinct from 1
    or p_relationship is null or p_relationship not in ('new_goal','clarification','repair')
    or ((p_relationship='new_goal') is distinct from (p_parent_turn_id is null))
    or p_locale is null or p_locale not in ('zh','en','es','ru','ar')
    or not turn_private.valid_text(p_text,4000) then raise exception 'INVALID_INPUT'; end if;
  if not turn_private.text_policy_current(p_policy_id) then raise exception 'DATA_POLICY_BLOCKED'; end if;
  select * into c from turn_private.text_consents where owner_id=u and policy_id=p_policy_id and revoked_at is null for share;
  if not found then raise exception 'DATA_POLICY_BLOCKED'; end if;
  digest:=encode(pg_catalog.sha256(convert_to(jsonb_build_array(p_thread_id,p_turn_id,p_idempotency_key,p_policy_id,p_locale,p_text,p_task_id,p_scope_version,p_relationship,p_parent_turn_id,p_city)::text,'UTF8')),'hex');
  -- Shared identity locks precede thread locks; acquire the pair in UUID order.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('service-task-identity:'||least(p_task_id,p_turn_id)::text,0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('service-task-identity:'||greatest(p_task_id,p_turn_id)::text,0));
  if p_relationship='new_goal' then
    insert into public.chat_threads(id,owner_id) values(p_thread_id,u) on conflict do nothing;
  end if;
  perform 1 from public.chat_threads where id=p_thread_id and owner_id=u and status='active' and trip_id is null for update;
  if not found then raise exception 'FORBIDDEN'; end if;
  select * into s from turn_private.service_tasks where id=p_task_id for update;
  if found then
    if s.owner_id<>u or s.thread_id<>p_thread_id or s.policy_id<>p_policy_id or s.consent_id<>c.consent_id
      or s.scope_version<>p_scope_version or s.expected_result<>'reviewed_answer' then raise exception 'SERVICE_TASK_CONFLICT'; end if;
    perform 1 from turn_private.text_content g join public.turns t on t.id=g.turn_id and t.owner_id=u
      where g.turn_id=s.goal_turn_id and g.owner_id=u and g.hidden_at is null;
    if not found then raise exception 'DATA_POLICY_BLOCKED'; end if;
    select * into prior from turn_private.service_task_turns where owner_id=u and task_id=s.id and idempotency_key=p_idempotency_key;
    if found then
      if prior.request_digest<>digest then raise exception 'IDEMPOTENCY_KEY_REUSE'; end if;
      -- Existing admission rechecks original content visibility/consent and never enqueues again.
      result:=public.start_text_turn(p_thread_id,p_turn_id,p_idempotency_key,p_policy_id,p_locale,p_text);
      if result->>'kind'<>'accepted' then raise exception 'DATA_POLICY_BLOCKED'; end if;
      return result||jsonb_build_object('serviceTaskId',s.id,'scopeVersion',s.scope_version,'relationship',prior.relationship,'parentTurnId',prior.parent_turn_id);
    end if;
    if (select count(*) from turn_private.service_task_turns where task_id=s.id)>=4 then raise exception 'SERVICE_TASK_CONFLICT'; end if;
    if not exists(select 1 from turn_private.grounded_turns g where g.turn_id=s.goal_turn_id and g.city=p_city and g.locale=p_locale) then raise exception 'SERVICE_TASK_CONFLICT'; end if;
    if p_relationship='new_goal' or s.last_turn_id is distinct from p_parent_turn_id then raise exception 'SERVICE_TASK_CONFLICT'; end if;
    select g.* into parent from turn_private.text_content g join public.turns t on t.id=g.turn_id and t.owner_id=u
      where g.turn_id=p_parent_turn_id and g.owner_id=u and g.thread_id=p_thread_id and g.hidden_at is null
      and t.status in ('completed','failed');
    if not found or parent.policy_id<>p_policy_id or parent.consent_id<>c.consent_id
      or (p_relationship='clarification' and parent.output_kind is distinct from 'clarification')
      or (p_relationship='repair' and parent.output_kind is distinct from 'technical_failure') then raise exception 'SERVICE_TASK_CONFLICT'; end if;
  else
    if p_relationship<>'new_goal' or exists(select 1 from public.turns where thread_id=p_thread_id)
      or exists(select 1 from public.turns where id=p_task_id)
      or exists(select 1 from turn_private.text_content where thread_id=p_thread_id or turn_id=p_task_id)
      or exists(select 1 from public.model_budget_attempts where task_id=p_task_id)
      or exists(select 1 from turn_private.service_tasks where thread_id=p_thread_id)
      then raise exception 'SERVICE_TASK_CONFLICT'; end if;
    insert into turn_private.service_tasks(id,owner_id,thread_id,goal_turn_id,last_turn_id,policy_id,consent_id,scope_version,expected_result,goal_digest)
      values(p_task_id,u,p_thread_id,p_turn_id,p_turn_id,p_policy_id,c.consent_id,p_scope_version,'reviewed_answer',
        encode(pg_catalog.sha256(convert_to(p_text,'UTF8')),'hex'));
  end if;
  if exists(select 1 from turn_private.service_tasks where id=p_turn_id)
    or exists(select 1 from public.turns where id=p_turn_id)
    or exists(select 1 from turn_private.text_content where turn_id=p_turn_id)
    then raise exception 'SERVICE_TASK_CONFLICT'; end if;
  insert into turn_private.service_task_turns(turn_id,task_id,owner_id,parent_turn_id,relationship,idempotency_key,request_digest)
    values(p_turn_id,p_task_id,u,p_parent_turn_id,p_relationship,p_idempotency_key,digest);
  insert into turn_private.grounded_turns(turn_id,owner_id,task_id,city,locale) values(p_turn_id,u,p_task_id,p_city,p_locale);
  result:=public.start_text_turn(p_thread_id,p_turn_id,p_idempotency_key,p_policy_id,p_locale,p_text);
  if result->>'kind'<>'accepted' or result->>'reused'<>'false' then raise exception 'SERVICE_TASK_CONFLICT'; end if;
  update turn_private.service_tasks set last_turn_id=p_turn_id where id=p_task_id;
  return result||jsonb_build_object('serviceTaskId',p_task_id,'scopeVersion',p_scope_version,'relationship',p_relationship,'parentTurnId',p_parent_turn_id);
end
